INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 21, 'theory', 'Quiz: CSS Responsive Design, States and Animations');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 21, 0, 'What does the viewport meta tag with the value width=device-width do?', '["It disables pinch zoom on the page", "It sets the maximum width of all images", "It tells a mobile browser to make the window width equal to the device screen width and not pretend to be a desktop", "It turns on the dark theme on phones"]', 2, 'Without this meta tag, a phone assumes a window about a thousand pixels wide and shrinks the whole page, and width media queries work wrong. With width=device-width, the viewport width equals the real screen width.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 21, 1, 'What does the mobile-first approach mean in CSS?', '["The base rules are written for a narrow screen, and @media (min-width: …) is added for wide ones", "A separate site is created for phones at a different address", "All rules are written for the desktop and then switched off with max-width queries", "The page is tested on a phone only"]', 0, 'The phone gets the basic, lightest set of styles, and the layout is extended as the window grows through min-width. This way you do not have to override and cancel extra rules.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 21, 2, 'How does a container query (@container) differ from a media query?', '["It works only in the print version of the page", "It reacts to the background color of the parent", "It replaces the viewport meta tag", "It looks at the size of the nearest parent container (container-type), not at the window size"]', 3, 'You set container-type on the parent, and the @container rule fires based on its size. So the same component looks different in a wide column and in a narrow sidebar regardless of the window width.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 21, 3, 'Why is it recommended to animate transform and opacity rather than left or width?', '["Because left and width cannot be used in a transition", "They run at the compositing step, without recalculating the layout or repainting, and do not disturb the rest of the page", "Because they work without specifying a duration", "Because all browsers understand them, while other properties are understood only by some"]', 1, 'Changing left or width forces the browser to recalculate the layout and repaint the neighbors. Transform and opacity only change how the layer is composited on the graphics card, so the animation stays smooth even on weak phones.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 21, 4, 'What is the @media (prefers-reduced-motion: reduce) query for?', '["To reduce the size of animation files", "To slow down all transitions by half", "To switch off or soften motion for people who turned on the reduce motion setting in their system", "To detect a weak device and lower the frame rate"]', 2, 'The setting is needed by people who get sick from parallax and spinning, and where there is a risk of seizures. The browser passes it to the page, and inside this query you switch the animation off or replace it with a soft fade-in.');
